1	package com.example.starter.water;
2	
3	import com.example.starter.water.WaterRepository.AllocationRow;
4	import com.example.starter.water.WaterRepository.CommandRow;
5	import com.example.starter.water.WaterRepository.CurtailmentRow;
6	import com.example.starter.water.WaterRepository.TransferRow;
7	import com.example.starter.water.WaterRepository.WindowRow;
8	import com.example.starter.water.dto.Dtos.AllocationResponse;
9	import com.example.starter.water.dto.Dtos.CapacityResponse;
10	import com.example.starter.water.dto.Dtos.CurtailmentResponse;
11	import com.example.starter.water.dto.Dtos.HistoryResponse;
12	import com.example.starter.water.dto.Dtos.TransferListResponse;
13	import com.example.starter.water.dto.Dtos.TransferResponse;
14	import com.example.starter.water.dto.Dtos.WindowResponse;
15	import com.fasterxml.jackson.databind.ObjectMapper;
16	import org.springframework.dao.DuplicateKeyException;
17	import org.springframework.stereotype.Service;
18	import org.springframework.transaction.PlatformTransactionManager;
19	import org.springframework.transaction.support.TransactionTemplate;
20	
21	import java.math.BigDecimal;
22	import java.time.Instant;
23	import java.time.format.DateTimeParseException;
24	import java.util.List;
25	import java.util.function.Supplier;
26	import java.util.regex.Pattern;
27	
28	/**
29	 * 灌区配水业务服务。
30	 *
31	 * <p>幂等：每个写命令携带 commandKey，事务内先占位插入命令行再执行业务并写回响应；
32	 * 同键同参重放返回首次结果，同键改参返回 409。</p>
33	 *
34	 * <p>并发：批准申请与创建/取消限供在同一事务内先对窗口行 SELECT ... FOR UPDATE，
35	 * 按事务提交顺序生效，保证已批准总量永不超过最终可用总量。</p>
36	 */
37	@Service
38	public class WaterService {
39	
40	    static final String STATUS_REQUESTED = "REQUESTED";
41	    static final String STATUS_APPROVED = "APPROVED";
42	    static final String STATUS_CANCELLED = "CANCELLED";
43	
44	    private static final long NANOS_PER_SECOND = 1_000_000_000L;
45	    private static final Pattern AMOUNT_PATTERN = Pattern.compile("\\d{1,16}(\\.\\d{1,3})?");
46	    private static final Pattern KEY_PATTERN = Pattern.compile("[\\w.\\-:]{1,128}");
47	
48	    private final WaterRepository repository;
49	    private final TransactionTemplate tx;
50	    private final ObjectMapper objectMapper;
51	
52	    public WaterService(WaterRepository repository, PlatformTransactionManager transactionManager,
53	                        ObjectMapper objectMapper) {
54	        this.repository = repository;
55	        this.tx = new TransactionTemplate(transactionManager);
56	        this.objectMapper = objectMapper;
57	    }
58	
59	    // ------------------------------------------------------------------
60	    // 命令入口
61	    // ------------------------------------------------------------------
62	
63	    /** 创建供水窗口。 */
64	    public WindowResponse createWindow(String commandKey, String windowKey, String channelId,
65	                                       String startUtc, String endUtc, String plannedVolume) {
66	        requireKey("commandKey", commandKey);
67	        requireKey("windowKey", windowKey);
68	        requireKey("channelId", channelId);
69	        long startNanos = parseInstant("startUtc", startUtc);
70	        long endNanos = parseInstant("endUtc", endUtc);
71	        if (startNanos >= endNanos) {
72	            throw ApiException.badRequest("INVALID_ARGUMENT", "startUtc 必须早于 endUtc");
73	        }
74	        BigDecimal planned = parseAmount("plannedVolume", plannedVolume);
75	        String params = "WINDOW_CREATE|" + windowKey + "|" + channelId + "|" + startNanos + "|" + endNanos
76	                + "|" + planned.toPlainString();
77	        return runCommand("WINDOW_CREATE", commandKey, params, WindowResponse.class, () -> {
78	            if (repository.existsOverlappingWindow(channelId, startNanos, endNanos)) {
79	                throw ApiException.conflict("WINDOW_OVERLAP", "同一渠道存在时间重叠的供水窗口");
80	            }
81	            long id = repository.insertWindow(windowKey, channelId, startNanos, endNanos, planned, nowNanos());
82	            WindowRow row = repository.findWindowById(id);
83	            return toWindowResponse(row, null);
84	        });
85	    }
86	
87	    /** 提交配水申请，申请人为 actor。 */
88	    public AllocationResponse submitAllocation(String commandKey, String allocationKey, Long windowId,
89	                                               String userId, String amount, String actor) {
90	        requireKey("commandKey", commandKey);
91	        requireKey("allocationKey", allocationKey);
92	        requireKey("userId", userId);
93	        requireKey("X-Actor-Id", actor);
94	        if (windowId == null) {
95	            throw ApiException.badRequest("INVALID_ARGUMENT", "windowId 不能为空");
96	        }
97	        BigDecimal qty = parseAmount("amount", amount);
98	        String params = "ALLOCATION_SUBMIT|" + allocationKey + "|" + windowId + "|" + userId + "|"
99	                + qty.toPlainString() + "|" + actor;
100	        return runCommand("ALLOCATION_SUBMIT", commandKey, params, AllocationResponse.class, () -> {
101	            WindowRow window = repository.lockWindowById(windowId);
102	            if (window == null) {
103	                throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
104	            }
105	            long id = repository.insertAllocation(allocationKey, windowId, userId, qty, actor, nowNanos());
106	            return toAllocationResponse(repository.findAllocationByKey(allocationKey));
107	        });
108	    }
109	
110	    /** 批准申请：加入本申请后已批准总量不得超过当前可用总量，否则 422。 */
111	    public AllocationResponse approveAllocation(String commandKey, String allocationKey) {
112	        requireKey("commandKey", commandKey);
113	        requireKey("allocationKey", allocationKey);
114	        String params = "ALLOCATION_APPROVE|" + allocationKey;
115	        return runCommand("ALLOCATION_APPROVE", commandKey, params, AllocationResponse.class, () -> {
116	            AllocationRow allocation = repository.findAllocationByKey(allocationKey);
117	            if (allocation == null) {
118	                throw ApiException.notFound("ALLOCATION_NOT_FOUND", "配水申请不存在: " + allocationKey);
119	            }
120	            WindowRow window = lockWindowOf(allocation);
121	            // 窗口锁内重读申请，避免与转让/取消并发时使用过期状态与持有额度
122	            allocation = repository.lockAllocationByKey(allocationKey);
123	            switch (allocation.status()) {
124	                case STATUS_CANCELLED ->
125	                        throw ApiException.conflict("ALLOCATION_CANCELLED", "已取消的申请不能批准");
126	                case STATUS_APPROVED ->
127	                        throw ApiException.conflict("ALLOCATION_ALREADY_APPROVED", "申请已批准，不能重复批准");
128	                default -> {
129	                }
130	            }
131	            BigDecimal available = availableTotal(window);
132	            BigDecimal approved = repository.sumApprovedAmount(window.id());
133	            if (approved.add(allocation.amount()).compareTo(available) > 0) {
134	                throw ApiException.quotaExceeded("批准后将超过当前可用总量 " + fmt(available));
135	            }
136	            repository.updateAllocationStatus(allocation.id(), STATUS_APPROVED, nowNanos());
137	            return toAllocationResponse(repository.findAllocationByKey(allocationKey));
138	        });
139	    }
140	
141	    /** 取消申请：仅申请人本人可取消 REQUESTED/APPROVED，取消不可恢复并立即释放水量。 */
142	    public AllocationResponse cancelAllocation(String commandKey, String allocationKey, String actor) {
143	        requireKey("commandKey", commandKey);
144	        requireKey("allocationKey", allocationKey);
145	        requireKey("X-Actor-Id", actor);
146	        String params = "ALLOCATION_CANCEL|" + allocationKey + "|" + actor;
147	        return runCommand("ALLOCATION_CANCEL", commandKey, params, AllocationResponse.class, () -> {
148	            AllocationRow allocation = repository.findAllocationByKey(allocationKey);
149	            if (allocation == null) {
150	                throw ApiException.notFound("ALLOCATION_NOT_FOUND", "配水申请不存在: " + allocationKey);
151	            }
152	            lockWindowOf(allocation);
153	            // 窗口锁内重读申请，避免与转让/并发取消使用过期状态
154	            allocation = repository.lockAllocationByKey(allocationKey);
155	            if (!allocation.requester().equals(actor)) {
156	                throw ApiException.conflict("NOT_OWNER", "只有申请人本人可以取消该申请");
157	            }
158	            if (STATUS_CANCELLED.equals(allocation.status())) {
159	                throw ApiException.conflict("ALLOCATION_ALREADY_CANCELLED", "申请已取消，不能重复取消");
160	            }
161	            repository.updateAllocationStatus(allocation.id(), STATUS_CANCELLED, nowNanos());
162	            return toAllocationResponse(repository.findAllocationByKey(allocationKey));
163	        });
164	    }
165	
166	    /**
167	     * 同窗口额度原子转让：源申请人（actor）把自己 APPROVED 申请的额度转给同窗口、不同用水户的
168	     * REQUESTED 目标申请，转让额等于目标原申请水量的全部额度。
169	     * 源扣减、目标批准、不可变流水在同一事务完成，窗口已批准总量不变；失败回滚无任何额度变化。
170	     */
171	    public TransferResponse transferAllocation(String commandKey, String transferKey, String sourceAllocationKey,
172	                                               String targetAllocationKey, String actor) {
173	        requireKey("commandKey", commandKey);
174	        requireKey("transferKey", transferKey);
175	        requireKey("sourceAllocationKey", sourceAllocationKey);
176	        requireKey("targetAllocationKey", targetAllocationKey);
177	        requireKey("X-Actor-Id", actor);
178	        String params = "TRANSFER|" + transferKey + "|" + sourceAllocationKey + "|" + targetAllocationKey + "|"
179	                + actor;
180	        return runCommand("TRANSFER", commandKey, params, TransferResponse.class, () -> {
181	            if (repository.findTransferByKey(transferKey) != null) {
182	                throw ApiException.conflict("TRANSFER_KEY_REUSED", "transferKey 已被使用: " + transferKey);
183	            }
184	            AllocationRow source = repository.findAllocationByKey(sourceAllocationKey);
185	            if (source == null) {
186	                throw ApiException.notFound("SOURCE_ALLOCATION_NOT_FOUND",
187	                        "转出申请不存在: " + sourceAllocationKey);
188	            }
189	            AllocationRow target = repository.findAllocationByKey(targetAllocationKey);
190	            if (target == null) {
191	                throw ApiException.notFound("TARGET_ALLOCATION_NOT_FOUND",
192	                        "转入申请不存在: " + targetAllocationKey);
193	            }
194	            // 先锁窗口行，与普通批准、取消、限供调整按事务提交顺序串行裁决
195	            lockWindowOf(source);
196	            // 窗口锁内再锁定源/目标申请行，得到最新状态与持有额度
197	            AllocationRow lockedSource = repository.lockAllocationByKey(sourceAllocationKey);
198	            AllocationRow lockedTarget = repository.lockAllocationByKey(targetAllocationKey);
199	            if (!lockedSource.requester().equals(actor)) {
200	                throw ApiException.conflict("NOT_OWNER", "只有转出申请人本人可以发起转让");
201	            }
202	            if (!STATUS_APPROVED.equals(lockedSource.status())) {
203	                throw ApiException.conflict("SOURCE_NOT_APPROVED", "转出申请必须为 APPROVED 状态");
204	            }
205	            if (!STATUS_REQUESTED.equals(lockedTarget.status())) {
206	                throw ApiException.conflict("TARGET_NOT_REQUESTED", "转入申请必须为 REQUESTED 状态");
207	            }
208	            if (lockedSource.windowId() != lockedTarget.windowId()) {
209	                throw ApiException.conflict("DIFFERENT_WINDOW", "转让双方必须属于同一供水窗口");
210	            }
211	            if (lockedSource.userId().equals(lockedTarget.userId())) {
212	                throw ApiException.conflict("SAME_USER", "转让双方必须属于不同用水户");
213	            }
214	            BigDecimal amount = lockedTarget.amount();
215	            if (lockedSource.heldAmount().compareTo(amount) < 0) {
216	                throw ApiException.quotaExceeded("源申请当前持有额度 " + fmt(lockedSource.heldAmount())
217	                        + " 不足，无法转让 " + fmt(amount));
218	            }
219	            long now = nowNanos();
220	            repository.decrementHeldAmount(lockedSource.id(), amount, now);
221	            repository.updateAllocationStatus(lockedTarget.id(), STATUS_APPROVED, now);
222	            try {
223	                repository.insertTransfer(transferKey, lockedSource.windowId(), sourceAllocationKey,
224	                        targetAllocationKey, amount, actor, now);
225	            } catch (DuplicateKeyException e) {
226	                // 并发复用同一 transferKey（换 commandKey）：事务回滚，额度无变化
227	                throw ApiException.conflict("TRANSFER_KEY_REUSED", "transferKey 已被使用: " + transferKey);
228	            }
229	            return toTransferResponse(repository.findTransferByKey(transferKey));
230	        });
231	    }
232	
233	    /** 查询窗口全部转让流水（不可变），按发生顺序返回。 */
234	    public TransferListResponse getTransfers(long windowId) {
235	        WindowRow window = repository.findWindowById(windowId);
236	        if (window == null) {
237	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
238	        }
239	        List<TransferResponse> transfers = repository.listTransfers(windowId).stream()
240	                .map(this::toTransferResponse).toList();
241	        return new TransferListResponse(windowId, transfers);
242	    }
243	
244	    /** 创建限供：仅当当前已批准总量不超过拟定限供水量时允许。 */
245	    public CurtailmentResponse createCurtailment(String commandKey, long windowId, String volume) {
246	        requireKey("commandKey", commandKey);
247	        BigDecimal qty = parseAmount("volume", volume);
248	        String params = "CURTAILMENT_CREATE|" + windowId + "|" + qty.toPlainString();
249	        return runCommand("CURTAILMENT_CREATE", commandKey, params, CurtailmentResponse.class, () -> {
250	            WindowRow window = repository.lockWindowById(windowId);
251	            if (window == null) {
252	                throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
253	            }
254	            if (qty.compareTo(window.plannedVolume()) > 0) {
255	                throw ApiException.badRequest("INVALID_ARGUMENT", "限供水量不能超过计划水量 " + fmt(window.plannedVolume()));
256	            }
257	            if (repository.findActiveCurtailment(windowId) != null) {
258	                throw ApiException.conflict("CURTAILMENT_EXISTS", "窗口已存在生效中的限供");
259	            }
260	            BigDecimal approved = repository.sumApprovedAmount(windowId);
261	            if (approved.compareTo(qty) > 0) {
262	                throw ApiException.conflict("CURTAILMENT_BELOW_APPROVED",
263	                        "当前已批准总量 " + fmt(approved) + " 超过拟定限供水量 " + fmt(qty));
264	            }
265	            long id = repository.insertCurtailment(windowId, qty, nowNanos());
266	            return toCurtailmentResponse(repository.findActiveCurtailment(windowId));
267	        });
268	    }
269	
270	    /** 取消当前生效限供，恢复计划水量。 */
271	    public CurtailmentResponse cancelCurtailment(String commandKey, long windowId) {
272	        requireKey("commandKey", commandKey);
273	        String params = "CURTAILMENT_CANCEL|" + windowId;
274	        return runCommand("CURTAILMENT_CANCEL", commandKey, params, CurtailmentResponse.class, () -> {
275	            WindowRow window = repository.lockWindowById(windowId);
276	            if (window == null) {
277	                throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
278	            }
279	            CurtailmentRow active = repository.findActiveCurtailment(windowId);
280	            if (active == null) {
281	                throw ApiException.conflict("NO_ACTIVE_CURTAILMENT", "窗口没有生效中的限供");
282	            }
283	            repository.cancelCurtailment(active.id(), nowNanos());
284	            List<CurtailmentRow> all = repository.listCurtailments(windowId);
285	            return all.stream().filter(c -> c.id() == active.id()).findFirst()
286	                    .map(this::toCurtailmentResponse).orElseThrow();
287	        });
288	    }
289	
290	    /** 查询窗口当前可用容量。 */
291	    public CapacityResponse getCapacity(long windowId) {
292	        WindowRow window = repository.findWindowById(windowId);
293	        if (window == null) {
294	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
295	        }
296	        CurtailmentRow active = repository.findActiveCurtailment(windowId);
297	        BigDecimal available = active != null ? active.volume() : window.plannedVolume();
298	        BigDecimal approved = repository.sumApprovedAmount(windowId);
299	        return new CapacityResponse(window.id(), fmt(window.plannedVolume()),
300	                active != null ? fmt(active.volume()) : null, fmt(available), fmt(approved),
301	                fmt(available.subtract(approved)));
302	    }
303	
304	    /** 查询窗口历史明细：窗口 + 全部申请 + 全部限供。 */
305	    public HistoryResponse getHistory(long windowId) {
306	        WindowRow window = repository.findWindowById(windowId);
307	        if (window == null) {
308	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
309	        }
310	        CurtailmentRow active = repository.findActiveCurtailment(windowId);
311	        List<AllocationResponse> allocations = repository.listAllocations(windowId).stream()
312	                .map(this::toAllocationResponse).toList();
313	        List<CurtailmentResponse> curtailments = repository.listCurtailments(windowId).stream()
314	                .map(this::toCurtailmentResponse).toList();
315	        return new HistoryResponse(toWindowResponse(window, active), allocations, curtailments);
316	    }
317	
318	    // ------------------------------------------------------------------
319	    // 幂等命令框架
320	    // ------------------------------------------------------------------
321	
322	    /**
323	     * 在单事务内执行幂等命令：先占位插入命令行，再执行业务并写回响应。
324	     * 并发同键时占位插入会因唯一约束失败，随后读取已提交的首次结果重放或报 409。
325	     */
326	    private <T> T runCommand(String operation, String commandKey, String params, Class<T> type,
327	                             Supplier<T> business) {
328	        try {
329	            return tx.execute(status -> {
330	                CommandRow existing = repository.findCommand(commandKey);
331	                if (existing != null) {
332	                    return replay(existing, operation, params, type);
333	                }
334	                repository.insertCommand(commandKey, operation, params, nowNanos());
335	                T result = business.get();
336	                repository.updateCommandResponse(commandKey, toJson(result));
337	                return result;
338	            });
339	        } catch (DuplicateKeyException e) {
340	            CommandRow committed = repository.findCommand(commandKey);
341	            if (committed == null || committed.response() == null) {
342	                throw ApiException.conflict("COMMAND_CONFLICT", "相同 commandKey 的命令正在处理，请重试");
343	            }
344	            return replay(committed, operation, params, type);
345	        }
346	    }
347	
348	    private <T> T replay(CommandRow existing, String operation, String params, Class<T> type) {
349	        if (!existing.operation().equals(operation) || !existing.params().equals(params)) {
350	            throw ApiException.conflict("COMMAND_KEY_REUSED", "相同 commandKey 但参数不同，拒绝重放");
351	        }
352	        return fromJson(existing.response(), type);
353	    }
354	
355	    // ------------------------------------------------------------------
356	    // 内部工具
357	    // ------------------------------------------------------------------
358	
359	    private WindowRow lockWindowOf(AllocationRow allocation) {
360	        WindowRow window = repository.lockWindowById(allocation.windowId());
361	        if (window == null) {
362	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + allocation.windowId());
363	        }
364	        return window;
365	    }
366	
367	    private BigDecimal availableTotal(WindowRow window) {
368	        CurtailmentRow active = repository.findActiveCurtailment(window.id());
369	        return active != null ? active.volume() : window.plannedVolume();
370	    }
371	
372	    private WindowResponse toWindowResponse(WindowRow row, CurtailmentRow active) {
373	        BigDecimal available = active != null ? active.volume() : row.plannedVolume();
374	        return new WindowResponse(row.id(), row.windowKey(), row.channelId(), toIso(row.startNanos()),
375	                toIso(row.endNanos()), fmt(row.plannedVolume()),
376	                active != null ? fmt(active.volume()) : null, fmt(available), toIso(row.createdNanos()));
377	    }
378	
379	    private AllocationResponse toAllocationResponse(AllocationRow row) {
380	        return new AllocationResponse(row.allocationKey(), row.windowId(), row.userId(), fmt(row.amount()),
381	                fmt(row.heldAmount()), row.requester(), row.status(),
382	                toIso(row.createdNanos()), toIso(row.updatedNanos()));
383	    }
384	
385	    private TransferResponse toTransferResponse(TransferRow row) {
386	        return new TransferResponse(row.transferKey(), row.windowId(), row.sourceAllocationKey(),
387	                row.targetAllocationKey(), fmt(row.amount()), row.actor(), toIso(row.createdNanos()));
388	    }
389	
390	    private CurtailmentResponse toCurtailmentResponse(CurtailmentRow row) {
391	        return new CurtailmentResponse(row.id(), row.windowId(), fmt(row.volume()), row.status(),
392	                toIso(row.createdNanos()), row.cancelledNanos() == null ? null : toIso(row.cancelledNanos()));
393	    }
394	
395	    static long nowNanos() {
396	        return toNanos(Instant.now());
397	    }
398	
399	    /** Instant -> UTC 纳秒时间戳。 */
400	    static long toNanos(Instant instant) {
401	        return Math.addExact(Math.multiplyExact(instant.getEpochSecond(), NANOS_PER_SECOND), instant.getNano());
402	    }
403	
404	    /** UTC 纳秒时间戳 -> Instant。 */
405	    static Instant toInstant(long nanos) {
406	        return Instant.ofEpochSecond(Math.floorDiv(nanos, NANOS_PER_SECOND),
407	                Math.floorMod(nanos, NANOS_PER_SECOND));
408	    }
409	
410	    static String toIso(long nanos) {
411	        return toInstant(nanos).toString();
412	    }
413	
414	    static long parseInstant(String field, String value) {
415	        if (value == null || value.isBlank()) {
416	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 不能为空");
417	        }
418	        try {
419	            return toNanos(Instant.parse(value.trim()));
420	        } catch (DateTimeParseException | ArithmeticException e) {
421	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 不是合法的 UTC 时刻: " + value);
422	        }
423	    }
424	
425	    /** 解析水量：十进制字符串，大于 0，最多 3 位小数。 */
426	    static BigDecimal parseAmount(String field, String value) {
427	        if (value == null || value.isBlank()) {
428	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 不能为空");
429	        }
430	        String trimmed = value.trim();
431	        if (!AMOUNT_PATTERN.matcher(trimmed).matches()) {
432	            throw ApiException.badRequest("INVALID_ARGUMENT",
433	                    field + " 必须为大于 0 的十进制字符串，最多 3 位小数: " + value);
434	        }
435	        BigDecimal amount = new BigDecimal(trimmed);
436	        if (amount.signum() <= 0) {
437	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 必须大于 0");
438	        }
439	        return amount;
440	    }
441	
442	    static void requireKey(String field, String value) {
443	        if (value == null || !KEY_PATTERN.matcher(value).matches()) {
444	            throw ApiException.badRequest("INVALID_ARGUMENT",
445	                    field + " 不能为空，且仅允许字母数字及 . - _ :，最长 128 字符");
446	        }
447	    }
448	
449	    /** 水量格式化为十进制字符串（去掉多余尾零）。 */
450	    static String fmt(BigDecimal value) {
451	        BigDecimal stripped = value.stripTrailingZeros();
452	        if (stripped.signum() == 0) {
453	            return "0";
454	        }
455	        return stripped.toPlainString();
456	    }
457	
458	    private String toJson(Object value) {
459	        try {
460	            return objectMapper.writeValueAsString(value);
461	        } catch (Exception e) {
462	            throw new IllegalStateException("响应序列化失败", e);
463	        }
464	    }
465	
466	    private <T> T fromJson(String json, Class<T> type) {
467	        try {
468	            return objectMapper.readValue(json, type);
469	        } catch (Exception e) {
470	            throw new IllegalStateException("响应反序列化失败", e);
471	        }
472	    }
